import java.io.ByteArrayOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;
import org.apache.avro.Schema;
import org.apache.avro.data.TimeConversions;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericDatumReader;
import org.apache.avro.generic.GenericDatumWriter;
import org.apache.avro.generic.GenericRecord;
import org.apache.avro.io.DecoderFactory;
import org.apache.avro.io.EncoderFactory;

public class ConsumerFixture {
  static Schema schema(String unit) {
    return new Schema.Parser().parse("""
      {"type":"record","name":"Event","fields":[
        {"name":"occurredAt","type":{"type":"long","logicalType":"%s"}}]}
      """.formatted(unit));
  }
  public static void main(String[] args) throws Exception {
    Properties config = new Properties();
    try (var input = Files.newInputStream(Path.of(args[0]))) { config.load(input); }
    Schema writer = switch (args[1]) {
      case "v1" -> schema("timestamp-millis");
      case "v2" -> schema("timestamp-micros");
      default -> throw new IllegalArgumentException("Unknown immutable writer id");
    };
    Schema selected = config.getProperty("reader.selection").equals("writer")
        ? writer : schema("timestamp-micros");
    GenericData data = new GenericData();
    data.addLogicalTypeConversion(new TimeConversions.TimestampMillisConversion());
    data.addLogicalTypeConversion(new TimeConversions.TimestampMicrosConversion());
    GenericRecord event = new GenericData.Record(writer);
    event.put("occurredAt", Long.parseLong(args[2]));
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    var encoder = EncoderFactory.get().binaryEncoder(output, null);
    new GenericDatumWriter<GenericRecord>(writer).write(event, encoder);
    encoder.flush();
    GenericRecord read = new GenericDatumReader<GenericRecord>(writer, selected, data)
        .read(null, DecoderFactory.get().binaryDecoder(output.toByteArray(), null));
    System.out.println(read.get("occurredAt"));
  }
}

